tracer.utils.filter_operators.source:
"""Shared filter contract helpers.

The filter vocabulary is a FE/BE API contract. Keep the canonical values in
``api_contracts/filter_contract.json`` and have both sides consume/check that
same artifact instead of adding local alias maps in individual endpoints.
"""

from __future__ import annotations

import json
import math
import re
import unicodedata
from functools import lru_cache
from pathlib import Path
from typing import Any

from tracer.utils.attribute_suggestion_contract import (
    TYPED_STRING_SUGGESTION_MAX_UTF8_BYTES as TYPED_STRING_SUGGESTION_MAX_UTF8_BYTES,
)


@lru_cache(maxsize=1)
def load_filter_contract() -> dict:
    current_path = Path(__file__).resolve()
    contract_paths = (
        current_path.parents[3] / "api_contracts" / "filter_contract.json",
        current_path.parents[1] / "contracts" / "filter_contract.json",
    )
    for contract_path in contract_paths:
        if contract_path.exists():
            with contract_path.open("r", encoding="utf-8") as fh:
                return json.load(fh)
    raise FileNotFoundError(
        "Could not find filter_contract.json in api_contracts/ or tracer/contracts/"
    )


_CONTRACT = load_filter_contract()
_OPERATORS = _CONTRACT["operators"]

NO_VALUE_FILTER_OPS: set[str] = set(_OPERATORS["noValue"])
LIST_FILTER_OPS: set[str] = set(_OPERATORS["list"])
RANGE_FILTER_OPS: set[str] = set(_OPERATORS["range"])
SPAN_ATTR_ALLOWED_OPS: dict[str, set[str]] = {
    filter_type: set(ops)
    for filter_type, ops in _OPERATORS["spanAttributeAllowed"].items()
}
STRUCTURED_SPAN_ATTR_ALLOWED_OPS: dict[str, set[str]] = {
    filter_type: set(ops)
    for filter_type, ops in _OPERATORS["structuredSpanAttributeAllowed"].items()
}
FILTER_TYPE_ALLOWED_OPS: dict[str, set[str]] = {
    filter_type: set(ops)
    for filter_type, ops in _OPERATORS["filterTypeAllowed"].items()
}
SESSION_NUMERIC_MEMBERSHIP_COLUMNS = frozenset(
    {
        "duration",
        "total_cost",
        "total_tokens",
        "traces_count",
        "total_traces_count",
    }
)
FIELD_TYPE_ALIASES: dict[str, str] = dict(_CONTRACT["fieldTypes"]["aliases"])
FILTER_COLUMN_TYPES: set[str] = set(_CONTRACT["columnTypes"]["allowed"])
COL_TYPE_ALIASES: dict[str, str] = dict(_CONTRACT["columnTypes"]["aliases"])

# Structured-array membership is compiled into bound ClickHouse IN sets inside
# each bounded classifier query. Keep both the element count and bound string
# payload finite so an authenticated request cannot inflate the query AST/set.
JSON_ARRAY_FILTER_MAX_MEMBERS = 64
JSON_ARRAY_FILTER_MAX_STRING_UTF8_BYTES = 4_096
JSON_ARRAY_FILTER_MAX_TOTAL_STRING_UTF8_BYTES = 65_536

# Flat JSON-object filters are evaluated only while replaying a finite latest-
# state candidate set.  These caps bound both the number of JSON path
# expressions added to that classifier and the total bound parameter payload.
JSON_MAP_FILTER_MAX_MEMBERS = 32
JSON_MAP_FILTER_MAX_KEY_UTF8_BYTES = 1_024
JSON_MAP_FILTER_MAX_TOTAL_KEY_UTF8_BYTES = 16_384
JSON_MAP_FILTER_MAX_STRING_UTF8_BYTES = 4_096
JSON_MAP_FILTER_MAX_TOTAL_STRING_UTF8_BYTES = 65_536
JSON_FILTER_SIGNED_INT_MIN = -(1 << 63)
JSON_FILTER_SIGNED_INT_MAX = (1 << 63) - 1
JSON_FILTER_UNSIGNED_INT_MAX = (1 << 64) - 1

_CANONICAL_UUID = re.compile(
    r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", re.IGNORECASE
)


def normalize_filter_type(filter_type: str | None) -> str:
    if not filter_type:
        return ""
    return FIELD_TYPE_ALIASES.get(str(filter_type).lower(), str(filter_type).lower())


def filter_op_is_allowed(
    filter_type: str | None,
    filter_op: str | None,
    *,
    column_id: str | None = None,
    column_type: str | None = None,
    allow_session_numeric_membership: bool = False,
) -> bool:
    """Return whether one field/operator pair is part of the public contract.

    Session aggregates are the one numeric family with finite membership
    semantics. The shared FE contract intentionally does not publish numeric
    ``in``/``not_in``, so callers must opt into that endpoint-specific extension
    explicitly. Keep it column- and family-scoped even after opt-in so ordinary
    scalar numbers and numeric span attributes retain the canonical vocabulary.
    """

    normalized_type = normalize_filter_type(filter_type)
    allowed_ops = FILTER_TYPE_ALLOWED_OPS.get(normalized_type)
    if allowed_ops is None:
        return False
    if filter_op in allowed_ops:
        return True
    return (
        allow_session_numeric_membership
        and normalized_type == "number"
        and filter_op in LIST_FILTER_OPS
        and isinstance(column_id, str)
        and column_id in SESSION_NUMERIC_MEMBERSHIP_COLUMNS
        and column_type == "SYSTEM_METRIC"
    )


def normalize_span_attribute_filter_type(
    filter_type: str | None,
    filter_value: object = None,
) -> str:
    """Canonicalize the value-sensitive structured span-attribute type.

    Historical clients call both JSON arrays and JSON objects ``json``.  A
    list value retains the existing ``json``/``list`` -> ``array`` contract;
    only an actual object value is canonicalized to ``map``.  Null operators
    have no value from which to infer a shape, so callers must send explicit
    ``map``/``object`` when they mean object existence.
    """

    raw_type = str(filter_type or "").lower()
    if raw_type == "json" and isinstance(filter_value, dict):
        return "map"
    return normalize_filter_type(raw_type)


def split_comma_joined_uuid_members(item: dict[str, Any]) -> dict[str, Any]:
    """Return a text in/not_in filter whose comma-joined UUID members are split.

    Every list member is one exact value, commas included: a picked system
    prompt or ``"Paris, France"`` must match verbatim. The exception is an
    untyped member made only of canonical UUIDs joined by commas, which is what
    a free-text value box sends when several ids are pasted into it; it becomes
    one member per id. Picker selections carry ``attribute_value_types`` and
    always stay exact, so a stored value that is itself a UUID list can still
    be matched by picking it.
    """

    config = item.get("filter_config")
    if not isinstance(config, dict) or config.get("attribute_value_types") is not None:
        return item
    values = config.get("filter_value")
    if (
        config.get("filter_op") not in LIST_FILTER_OPS
        or not isinstance(values, list)
        or normalize_span_attribute_filter_type(config.get("filter_type"), values)
        != "text"
    ):
        return item

    members: list[Any] = []
    for value in values:
        ids = (
            [part.strip() for part in value.split(",") if part.strip()]
            if isinstance(value, str) and "," in value
            else []
        )
        if ids and all(_CANONICAL_UUID.fullmatch(member_id) for member_id in ids):
            members.extend(ids)
        else:
            members.append(value)
    if members == values:
        return item
    return {**item, "filter_config": {**config, "filter_value": members}}


def validate_json_map_filter_value(value: object) -> dict[str, object]:
    """Return one deterministic, bounded flat JSON object or raise ValueError.

    Only non-null JSON scalars are accepted as member values.  Nested arrays
    and objects would require recursive path semantics and can inflate the
    classifier expression tree, so the public map contract rejects them.
    """

    if not isinstance(value, dict) or not value:
        raise ValueError("JSON map filters require a non-empty object value")
    if len(value) > JSON_MAP_FILTER_MAX_MEMBERS:
        raise ValueError(
            f"JSON map filters support at most {JSON_MAP_FILTER_MAX_MEMBERS} members"
        )

    normalized_items: list[tuple[str, object]] = []
    total_key_bytes = 0
    total_string_bytes = 0
    for key, member_value in value.items():
        if not isinstance(key, str) or not key:
            raise ValueError("JSON map member keys must be non-empty strings")
        try:
            encoded_key = key.encode("utf-8", errors="strict")
        except UnicodeEncodeError as exc:
            raise ValueError("JSON map member keys must be valid UTF-8") from exc
        if len(encoded_key) > JSON_MAP_FILTER_MAX_KEY_UTF8_BYTES:
            raise ValueError(
                "JSON map member key exceeds the "
                f"{JSON_MAP_FILTER_MAX_KEY_UTF8_BYTES} UTF-8 byte limit"
            )
        total_key_bytes += len(encoded_key)
        if total_key_bytes > JSON_MAP_FILTER_MAX_TOTAL_KEY_UTF8_BYTES:
            raise ValueError(
                "JSON map member keys exceed the "
                f"{JSON_MAP_FILTER_MAX_TOTAL_KEY_UTF8_BYTES} UTF-8 byte request limit"
            )
        if any(unicodedata.category(character) in {"Cc", "Cf"} for character in key):
            raise ValueError("JSON map member keys contain control characters")

        if member_value is None:
            raise ValueError("JSON map members must be non-null JSON scalars")
        if isinstance(member_value, str):
            try:
                encoded_value = member_value.encode("utf-8", errors="strict")
            except UnicodeEncodeError as exc:
                raise ValueError("JSON map string values must be valid UTF-8") from exc
            if len(encoded_value) > JSON_MAP_FILTER_MAX_STRING_UTF8_BYTES:
                raise ValueError(
                    "JSON map string value exceeds the "
                    f"{JSON_MAP_FILTER_MAX_STRING_UTF8_BYTES} UTF-8 byte limit"
                )
            total_string_bytes += len(encoded_value)
            if total_string_bytes > JSON_MAP_FILTER_MAX_TOTAL_STRING_UTF8_BYTES:
                raise ValueError(
                    "JSON map string values exceed the "
                    f"{JSON_MAP_FILTER_MAX_TOTAL_STRING_UTF8_BYTES} UTF-8 byte request limit"
                )
        elif isinstance(member_value, bool):
            pass
        elif isinstance(member_value, int):
            if not (
                JSON_FILTER_SIGNED_INT_MIN
                <= member_value
                <= JSON_FILTER_UNSIGNED_INT_MAX
            ):
                raise ValueError("JSON map integers must fit Int64 or UInt64")
        elif isinstance(member_value, float):
            if not math.isfinite(member_value):
                raise ValueError("JSON map numbers must be finite")
        else:
            raise ValueError(
                "Nested JSON map filter values are not supported; "
                "members must be scalars"
            )
        normalized_items.append((key, member_value))

    # Stable ordering keeps generated SQL/parameter names deterministic for
    # semantically identical objects sent with different JSON key ordering.
    return dict(sorted(normalized_items, key=lambda item: item[0].encode("utf-8")))


def normalize_col_type(col_type: str | None) -> str:
    if not col_type:
        return ""
    raw = str(col_type)
    return COL_TYPE_ALIASES.get(raw.lower(), raw)

tracer.services.clickhouse.query_builder.source:
"""
ClickHouse Filter Builder.

Translates the frontend filter JSON format into ClickHouse WHERE clause
fragments with parameterized values.  This module is the ClickHouse
counterpart of ``tracer.utils.filters.FilterEngine`` which operates on
Django ORM querysets.
"""

import math
import re
import uuid
from collections.abc import Callable
from typing import Any, NamedTuple

from tracer.services.clickhouse.query_builders.voice_filter_expressions import (
    VOICE_NORMALIZED_ROOT_SYSTEM_METRIC_EXPRS,
    voice_conversation_root_expression,
)
from tracer.utils.constants import (
    LIST_OPS,
    NO_VALUE_OPS,
    RANGE_OPS,
    SPAN_ATTR_ALLOWED_OPS,
    FilterType,
)

_SAFE_ATTR_KEY_RE = re.compile(r"^[a-zA-Z0-9._\-]+$")

_LEGACY_OP_ALIAS = {"is": "equals", "is_not": "not_equals"}

_LITERAL_TEXT_MATCH_OPS = frozenset(
    {"contains", "not_contains", "starts_with", "ends_with"}
)

# ``has_eval`` / ``has_annotation`` / ``my_annotations`` are derived per row
# from the authoritative eval and Score relations.  The flag is computed for
# every row and is therefore never NULL, so ``is_not_null`` constrains nothing
# and ``is_null`` matches nothing.  ``not_equals`` is compiled by negating the
# requested value, never by inferring intent from the value alone.
_BOOLEAN_META_PRESENCE_CONDITIONS = {"is_null": "0 = 1", "is_not_null": "1 = 1"}

_BOOLEAN_META_VALUE_OPS = frozenset({"equals", "not_equals"})


class EvalFilterMetadata(NamedTuple):
    """Authoritative PostgreSQL metadata for one eval-value filter id."""

    config_ids: tuple[str, ...]
    output_type: str


def resolve_eval_filter_metadata(
    eval_id: str,
    project_ids: list[str] | tuple[str, ...] | None,
) -> EvalFilterMetadata:
    """Resolve one eval-value filter exactly as the SQL compiler historically did.

    Database failures deliberately propagate. A malformed legacy identifier is
    a valid, authoritative no-match and is represented by an empty config set.
    """

    from django.core.exceptions import ValidationError

    from model_hub.models.evals_metric import EvalTemplate
    from tracer.models.custom_eval_config import CustomEvalConfig

    config_ids: tuple[str, ...] = ()
    output_type = "SCORE"
    try:
        cfg_qs = CustomEvalConfig.objects.filter(id=eval_id, deleted=False)
        if not cfg_qs.exists():
            cfg_qs = CustomEvalConfig.objects.filter(
                eval_template_id=eval_id, deleted=False
            )
        if project_ids:
            cfg_qs = cfg_qs.filter(project_id__in=project_ids)
        config_ids = tuple(str(value) for value in cfg_qs.values_list("id", flat=True))

        template_id = (
            cfg_qs.values_list("eval_template_id", flat=True).first()
            if config_ids
            else eval_id
        )
        template = (
            EvalTemplate.no_workspace_objects.filter(id=template_id, deleted=False)
            .values("config")
            .first()
        )
        if template and isinstance(template.get("config"), dict):
            normalized_output = (
                (template["config"].get("output") or "")
                .upper()
                .replace("/", "_")
                .replace(" ", "_")
            )
            if normalized_output in ("PASS_FAIL", "CHOICE", "CHOICES", "SCORE"):
                output_type = normalized_output
    except (TypeError, ValueError, ValidationError):
        config_ids = ()

    return EvalFilterMetadata(config_ids=config_ids, output_type=output_type)


def resolve_annotation_label_output_type(
    label_id: str,
    organization_id: str | None = None,
) -> str | None:
    """Resolve one annotation label's authoritative value type from PostgreSQL.

    The label's ``type`` is the only authoritative statement of what a Score
    row's JSON payload holds, so a compiler must not infer it from the
    operator or from an optional client hint.  Labels are org-scoped and may
    be attached to a workspace rather than to one project, so the tenancy
    fence here is the organization — the same fence the Score predicate
    itself carries.  Returns ``None`` when the identifier names no live label
    in scope; callers reject such a filter rather than compiling a predicate
    against a guessed type.
    """

    from django.core.exceptions import ValidationError

    from model_hub.models.develop_annotations import AnnotationsLabels

    try:
        labels = AnnotationsLabels.no_workspace_objects.filter(
            id=label_id, deleted=False
        )
        if organization_id:
            labels = labels.filter(organization_id=organization_id)
        return labels.values_list("type", flat=True).first()
    except (TypeError, ValueError, ValidationError):
        return None


def _voice_root_metric_expressions(
    expressions: dict[str, str], keys: tuple[str, ...]
) -> dict[str, str]:
    return {key: voice_conversation_root_expression(expressions[key]) for key in keys}


def normalize_filter_op(op: str | None) -> str | None:
    if op is None:
        return None
    return _LEGACY_OP_ALIAS.get(op, op)


def _unsupported_filter_shape(message: str) -> ValueError:
    """Build the shared bad-filter error that public readers map to HTTP 400.

    ``latest_filter_predicates`` imports this module, so the exception it owns
    can only be resolved at call time.  Raising a bare ``ValueError`` here
    would reach the views' generic handler and answer HTTP 500 for a filter
    the caller can correct.
    """

    from tracer.services.clickhouse.query_builders.latest_filter_predicates import (
        UnsupportedFilterShapeError,
    )

    return UnsupportedFilterShapeError(message)


def boolean_meta_presence_condition(filter_op: str | None) -> str | None:
    """Compile a presence operator on a derived boolean flag.

    Returns the finished constant predicate for ``is_null`` / ``is_not_null``,
    and ``None`` for every other operator — which the caller then resolves with
    :func:`parse_boolean_meta_filter`.
    """

    return _BOOLEAN_META_PRESENCE_CONDITIONS.get(normalize_filter_op(filter_op) or "")


class BooleanMetaFilterShapeError(ValueError):
    """The shared boolean meta-filter rule rejected a shape.

    Raised by :func:`resolve_boolean_meta_value` so the rule itself owns no
    public error class.  Each compiler re-raises it as the class its own
    reader maps to a response: the list and graph compilers as
    ``UnsupportedFilterShapeError`` (HTTP 400 for the whole read), the
    dashboard builder as ``InvalidMetricCombinationError`` (a per-widget
    message, so one nonsensical filter does not fail the whole query).
    """


def resolve_boolean_meta_value(
    column_id: str,
    filter_value: Any,
    operation: str | None,
) -> bool:
    """The one value rule behind every boolean meta-filter, in one place.

    Which operators carry a value, how a value coerces to a boolean, and that
    ``not_equals`` is compiled by negating the requested value rather than by
    inferring intent from the value alone.

    ``operation`` is already normalised by the caller, because the compilers
    reach this rule through different alias tables — the list and graph
    compilers through :func:`normalize_filter_op`, the dashboard through its
    own payload aliases — and normalising twice here would silently widen
    each compiler's accepted vocabulary to the other's.
    """

    if operation not in _BOOLEAN_META_VALUE_OPS:
        raise BooleanMetaFilterShapeError(
            f"{column_id} supports only equals, not_equals, is_null and is_not_null"
        )
    if isinstance(filter_value, bool):
        wanted = filter_value
    elif isinstance(filter_value, str) and filter_value.strip().lower() in {
        "true",
        "false",
    }:
        wanted = filter_value.strip().lower() == "true"
    else:
        raise BooleanMetaFilterShapeError(f"{column_id} requires a boolean value")
    return wanted if operation == "equals" else not wanted


def parse_boolean_meta_filter(
    column_id: str,
    filter_value: Any,
    filter_op: str | None,
) -> bool:
    """Resolve one boolean meta-filter to the presence its operator requires.

    Presence operators are deliberately not accepted here: they carry no value
    and callers compile them through :func:`boolean_meta_presence_condition`
    first.
    """

    try:
        return resolve_boolean_meta_value(
            column_id, filter_value, normalize_filter_op(filter_op)
        )
    except BooleanMetaFilterShapeError as exc:
        raise _unsupported_filter_shape(str(exc)) from exc


def build_literal_text_predicate(
    expression: str,
    param: str,
    filter_op: str,
    *,
    case_insensitive: bool,
) -> str:
    """Compile user text as a literal needle, never as a LIKE pattern."""

    if filter_op not in _LITERAL_TEXT_MATCH_OPS:
        raise ValueError(f"unsupported literal text operation: {filter_op!r}")

    haystack = f"toString({expression})"
    needle = f"toString(%({param})s)"
    if case_insensitive:
        haystack = f"lowerUTF8({haystack})"
        needle = f"lowerUTF8({needle})"
    if filter_op in {"contains", "not_contains"}:
        comparison = "= 0" if filter_op == "not_contains" else "> 0"
        return f"positionUTF8({haystack}, {needle}) {comparison}"
    function = "startsWith" if filter_op == "starts_with" else "endsWith"
    return f"{function}({haystack}, {needle})"


def build_numeric_filter_predicate(
    expression: str,
    filter_op: str | None,
    filter_value: Any,
    *,
    param_prefix: str,
    params: dict[str, Any],
) -> str:
    """Compile the canonical number-filter contract for a trusted expression.

    Aggregate aliases cannot be routed through the row-level filter builder,
    so session list and graph queries share this small compiler. Invalid value
    shapes fail closed instead of emitting malformed ClickHouse SQL.
    """

    normalized_op = normalize_filter_op(filter_op)
    if normalized_op == "is_null":
        return f"{expression} IS NULL"
    if normalized_op == "is_not_null":
        return f"{expression} IS NOT NULL"

    if normalized_op in RANGE_OPS:
        if not isinstance(filter_value, (list, tuple)) or len(filter_value) != 2:
            return "0 = 1"
        lower_param = f"{param_prefix}_lo"
        upper_param = f"{param_prefix}_hi"
        params[lower_param], params[upper_param] = filter_value
        sql_op = "NOT BETWEEN" if normalized_op == "not_between" else "BETWEEN"
        return f"{expression} {sql_op} %({lower_param})s AND %({upper_param})s"

    if normalized_op in LIST_OPS:
        if not isinstance(filter_value, (list, tuple)):
            return "0 = 1"
        values = tuple(filter_value)
        if not values:
            return "1 = 1" if normalized_op == "not_in" else "0 = 1"
        params[param_prefix] = values
        sql_op = "NOT IN" if normalized_op == "not_in" else "IN"
        return f"{expression} {sql_op} %({param_prefix})s"

    comparison_op = {
        "equals": "=",
        "not_equals": "!=",
        "greater_than": ">",
        "less_than": "<",
        "greater_than_or_equal": ">=",
        "less_than_or_equal": "<=",
    }.get(normalized_op)
    if comparison_op is None or filter_value is None:
        return "0 = 1"
    params[param_prefix] = filter_value
    return f"{expression} {comparison_op} %({param_prefix})s"


def build_annotation_value_predicate(
    filter_type: str,
    filter_op: str | None,
    filter_value: Any,
    *,
    bind: Callable[[str, Any], str],
) -> str:
    """Shared Score value truth; callers retain entity/latest/presence scope.

    ``bind`` allocates a code-owned parameter name in the caller's namespace.
    Invalid operands raise ValueError so no caller can silently drop a leaf.
    """
    kind = str(filter_type or "").strip().lower()
    op = normalize_filter_op(filter_op)
    values = (
        list(filter_value)
        if isinstance(filter_value, (list, tuple))
        else [filter_value]
    )

    def parameter(value: Any, prefix: str = "ann") -> str:
        return f"%({bind(prefix, value)})s"

    if kind == "number":
        expression = (
            "if(JSONHas(s.value, 'rating'), JSONExtractFloat(s.value, 'rating'), "
            "JSONExtractFloat(s.value, 'value'))"
        )
        # JSONExtractFloat defaults absent/null/wrong-type payloads to zero.
        domain = (
            "JSONType(s.value, if(JSONHas(s.value, 'rating'), 'rating', 'value')) "
            "IN ('Int64', 'UInt64', 'Double')"
        )

        def number(value: Any) -> float:
            if isinstance(value, bool):
                raise ValueError("annotation number requires a finite number")
            try:
                result = float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("annotation number requires a finite number") from exc
            if not math.isfinite(result):
                raise ValueError("annotation number requires a finite number")
            return result

        if op in RANGE_OPS:
            if not isinstance(filter_value, (list, tuple)) or len(values) != 2:
                raise ValueError("annotation range requires two values")
            lower, upper = (number(value) for value in values)
            sql_op = "NOT BETWEEN" if op == "not_between" else "BETWEEN"
            predicate = f"{expression} {sql_op} {parameter(lower, 'lo')} AND {parameter(upper, 'hi')}"
        elif op in LIST_OPS:
            if not values:
                return "1 = 1" if op == "not_in" else "0 = 1"
            sql_op = "NOT IN" if op == "not_in" else "IN"
            predicate = f"{expression} {sql_op} {parameter(tuple(number(value) for value in values))}"
        else:
            sql_op = {
                "equals": "=",
                "not_equals": "!=",
                "greater_than": ">",
                "greater_than_or_equal": ">=",
                "less_than": "<",
                "less_than_or_equal": "<=",
            }.get(op)
            if sql_op is None:
                raise ValueError("unsupported annotation number operation")
            predicate = f"{expression} {sql_op} {parameter(number(filter_value))}"
        return f"{domain} AND {predicate}"

    if kind in {"boolean", "thumbs"}:
        token_map = {
            "true": "up",
            "false": "down",
            "up": "up",
            "down": "down",
            "thumbs up": "up",
            "thumbs down": "down",
            "thumbs_up": "up",
            "thumbs_down": "down",
        }
        if op not in {"equals", "not_equals", "in", "not_in"} or not values:
            raise ValueError("invalid annotation thumbs operation or value")
        if kind == "boolean" and isinstance(filter_value, (list, tuple)):
            raise ValueError("annotation boolean requires a scalar vote")
        tokens = []
        for value in values:
            token = (
                token_map.get(str(value).strip().lower())
                if isinstance(value, (str, bool))
                else None
            )
            if token is None:
                raise ValueError("invalid annotation thumbs value")
            if token not in tokens:
                tokens.append(token)
        expression = "JSONExtractString(s.value, 'value')"
        # Blank/null/wrong-type votes are not down votes or negative witnesses.
        domain = f"{expression} IN ('up', 'down')"
        if kind == "boolean":
            sql_op = "!=" if op in {"not_equals", "not_in"} else "="
            operand = parameter(tokens[0])
        else:
            sql_op = "NOT IN" if op in {"not_equals", "not_in"} else "IN"
            operand = parameter(tuple(tokens))
        return f"{domain} AND {expression} {sql_op} {operand}"

    if kind == "text":
        expression = "JSONExtractString(s.value, 'text')"
        if op in _LITERAL_TEXT_MATCH_OPS:
            name = bind("ann", str(filter_value))
            predicate = build_literal_text_predicate(
                expression, name, op, case_insensitive=True
            )
        elif op in {"equals", "not_equals"}:
            sql_op = "!=" if op == "not_equals" else "="
            predicate = f"lowerUTF8({expression}) {sql_op} lowerUTF8({parameter(str(filter_value))})"
        elif op in LIST_OPS:
            values = [str(value) for value in values if value not in (None, "")]
            if not values:
                return "1 = 1" if op == "not_in" else "0 = 1"
            negate = "NOT " if op == "not_in" else ""
            predicate = (
                f"{negate}has(arrayMap(x -> lowerUTF8(x), {parameter(values)}), "
                f"lowerUTF8({expression}))"
            )
        else:
            raise ValueError("unsupported annotation text operation")
        return f"{expression} != '' AND {predicate}"

    if kind in {"array", "categorical"}:
        if op not in {
            "equals",
            "in",
            "contains",
            "not_equals",
            "not_in",
            "not_contains",
        }:
            raise ValueError("unsupported annotation categorical operation")
        negative = op in {"not_equals", "not_in", "not_contains"}
        if not values:
            return "1 = 1" if negative else "0 = 1"
        legacy_thumbs = {
            "thumbs up": "up",
            "thumbs down": "down",
            "thumbs_up": "up",
            "thumbs_down": "down",
        }
        conditions = []
        for value in values:
            condition = f"has(JSONExtract(s.value, 'selected', 'Array(String)'), {parameter(value)})"
            thumb = (
                legacy_thumbs.get(value.strip().lower())
                if isinstance(value, str)
                else None
            )
            if thumb is not None:
                condition = f"({condition} OR JSONExtractString(s.value, 'value') = {parameter(thumb)})"
            conditions.append(condition)
        combined = "(" + " OR ".join(conditions) + ")"
        return f"NOT {combined}" if negative else combined

    raise ValueError(f"unsupported annotation filter type: {kind!r}")


def _sanitize_key(key: str) -> str:
    """Validate a key is safe for use in ClickHouse expressions."""
    if not key or not _SAFE_ATTR_KEY_RE.match(key):
        raise ValueError(f"Invalid attribute key: {key!r}")
    return key


def _coerce_strict_bool(v: Any) -> int:
    """Native bool only; reject strings and ints."""
    if isinstance(v, bool):
        return 1 if v else 0
    raise ValueError(
        f"Invalid boolean filter value: {v!r} (expected native true/false)"
    )


_SPAN_ATTR_TYPE_META: dict[str, tuple[str, Callable[[Any], Any]]] = {
    FilterType.TEXT.value: (
        "span_attr_str",
        lambda v: v if isinstance(v, str) else str(v),
    ),
    FilterType.NUMBER.value: ("span_attr_num", lambda v: float(v)),
    FilterType.BOOLEAN.value: ("span_attr_bool", _coerce_strict_bool),
}


class ClickHouseFilterBuilder:
    """Translates frontend filter format to ClickHouse WHERE clauses.

    The frontend sends filters as a list of dicts::

        [
            {
                "column_id": "model",
                "filter_config": {
                    "col_type": "SYSTEM_METRIC",
                    "filter_type": "text",
                    "filter_op": "equals",
                    "filter_value": "gpt-4"
                }
            },
            ...
        ]

    This class translates each filter into a SQL fragment with ``%(param)s``
    style placeholders and collects the parameter values into a dict.

    Usage::

        fb = ClickHouseFilterBuilder(table="spans")
        where_clause, params = fb.translate(filters)
        # where_clause: "model = %(col_1)s AND cost > %(col_2)s"
        # params: {"col_1": "gpt-4", "col_2": 0.01}
    """

    # Column type constants matching ColType enum from filters.py
    NORMAL = "NORMAL"
    TRACE_END_USER = "TRACE_END_USER"
    SYSTEM_METRIC = "SYSTEM_METRIC"
    EVAL_METRIC = "EVAL_METRIC"
    SPAN_ATTRIBUTE = "SPAN_ATTRIBUTE"
    ANNOTATION = "ANNOTATION"

    # Query mode — whether the caller is paginating traces (root spans
    # only — wrap filters in `trace_id IN (...)` so child-span attributes
    # match the parent trace) or individual spans (no wrap; the filter
    # should apply to each span row directly).
    QUERY_MODE_TRACE = "trace"
    QUERY_MODE_SPAN = "span"

    # Explicit source-injection boundary. The eval-table rollout is independent
    # from the spans generation, so all builders honor the configured source.
    @staticmethod
    def _eval_logger_source(
        alias: str = "",
        include_cdc_tombstone_guard: bool = False,
    ) -> tuple[str, str]:
        from tracer.services.clickhouse.eval_logger_table import eval_logger_source

        return eval_logger_source(alias, include_cdc_tombstone_guard)

    # Numeric per-trace metrics where the trace list displays the
    # **root span**'s value. In QUERY_MODE_TRACE we restrict the inner
    # `trace_id IN (...)` subquery to root spans for these columns so
    # the filter result matches what the user sees in the row — without
    # this, a trace whose root has no tokens but a child LLM span does
    # would silently pass a `total_tokens > N` filter (TH-4044).
    ROOT_ONLY_SYSTEM_METRICS = {
        "total_tokens",
        "prompt_tokens",
        "completion_tokens",
        "cost",
        "avg_cost",
        "latency_ms",
        "avg_latency",
        "name",  # trace name = root span name; restrict to root spans to avoid child-span false positives
    }

    # System metric column mappings (frontend name -> ClickHouse column)
    #
    # The frontend may send either the simple column name (e.g.
    # ``total_tokens``) or the underlying OTel / openinference attribute
    # key (e.g. ``gen_ai.usage.total_tokens``, ``llm.token_count.total``).
    # Both refer to the same data — the ingest writer denormalises the
    # attribute into a top-level Int32 column. Aliasing here routes both
    # forms through ``_build_column_condition`` (which honours
